import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

class Todo {
    private String what;
    private boolean done;

    Todo(String what, boolean done) {
        this.what = what;
        this.done = done;
    }

    String getWhat() { return what; }
    boolean isDone() { return done; }
    void markDone() { done = true; }

    @Override
    public String toString() {
        return (done ? "[x] " : "[ ] ") + what;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        sc.nextLine();
        List<Todo> zhi = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            zhi.add(new Todo(sc.nextLine(), false));
        }
        zhi.get(0).markDone();
        for (int i = 0; i < zhi.size(); i++) {
            System.out.println((i + 1) + ". " + zhi.get(i));
        }
        System.out.println("一共 " + zhi.size() + " 件，头一件办完了：" + zhi.get(0).isDone());
    }
}

